'use strict';
const cases=[{id:1,title:'The Mystery of the Upside-Down Map',pdf:'Case1_UpsideDownMap_002.pdf',description:'Join Remy for the first Thinking Detectives adventure.',interactive:false},{id:2,title:'The Case of the Runaway Robot',pdf:'Case2_RunawayRobot_001.pdf',description:'A missing trophy. A delivery robot. Six facts—and somewhere to start.',interactive:true}];
const facts=["DASH-3's wheels have a double-chevron tread.",'Fresh double-chevron tracks curve from the curtain toward North Concourse.','The Service Passage door was locked before the demonstration. Its security seal is still unbroken.','Calamari wore his sunglasses on top of his head.','A blue balloon popped at 2:26.','The trophy ribbon had one crooked loop.'];
const hints=['What is the question asking you to find: a color, a time, or a direction?','Look for one fact about DASH-3 and another matching fact.','Compare wheel tread with tracks. Use the locked passage as a check.','Double-chevron tracks lead toward North Concourse; the other passage stayed sealed.'];
const key='thinking-detectives.case2.mission1.v1';
let s={chosen:[],path:'',answer:'',checked:false,spoken:false,hints:0,complete:false,verified:false};let storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&typeof saved==='object'){s={...s,...saved};s.chosen=Array.isArray(s.chosen)?s.chosen.filter(x=>Number.isInteger(x)&&x>=0&&x<6):[];s.hints=Math.max(0,Math.min(4,Number(s.hints)||0));}}catch{storageOK=false;}
// Old completion flags never substitute for the new explicit answer check.
if(typeof s.path!=='string')s.path='';
if(typeof s.answer!=='string')s.answer='';
function destinationMatches(value){
 const a=value.toLowerCase().normalize('NFKC').replace(/[’']/g,'').replace(/[^a-z\s-]/g,' ').replace(/-/g,' ').replace(/\s+/g,' ').trim();
 return /^(?:(?:i think |i think that )?(?:remy should investigate |remy should go to |we should investigate |we should go to |go to |investigate |check |look in |look at |head to |the answer is |my answer is |its |it is |toward |towards |at |in |to )?)?(?:the )?north\s*concourse$/.test(a);
}
function evaluateAnswer(state){
 if(!state.answer.trim())return {kind:'missing',text:'What place would you investigate? Add your answer so we can check it.'};
 if(!destinationMatches(state.answer))return {kind:'retry',text:'Good effort—you gave it a try! This answer needs another look. Give it another try :) If you’d like some help, use the hint section below to reveal one hint at a time.'};
 if(!state.chosen.length||(!state.path.trim()&&!state.spoken)||!state.checked)return {kind:'missing',text:'You found the destination—well done! Before continuing, choose your useful facts, show or explain your path, and check it. Then click Check My Answer again.'};
 if(!state.chosen.includes(0)||!state.chosen.includes(1))return {kind:'retry',text:'Good effort finding a destination! Now take another look at which facts support it and try again. If you’d like help, the hint section below lets you reveal one hint at a time.'};
 if(state.chosen.some(i=>i>2))return {kind:'retry',text:'Good effort—you found a useful trail! Take another look at your selected facts. Does each one help explain where DASH-3 went? Try again, or use the optional hint section below, one hint at a time.'};
 return {kind:'success',text:'You connected the matching wheels and tracks to North Concourse. Your answer is supported by those clues. You’re ready to continue!'};
}

s.verified=s.verified===true&&evaluateAnswer(s).kind==='success';
if(!s.verified)s.complete=false;
let feedback=s.verified?evaluateAnswer(s):null;
const app=document.getElementById('app');
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(key,JSON.stringify(s));}catch{storageOK=false;}const el=document.getElementById('saved');if(el)el.textContent=storageOK?'Your work is saved in this browser.':'Your work is available for this visit. Browser saving is unavailable.';}
function library(){app.innerHTML=`<section class="intro"><div class="eyebrow">CURIOUS MINDS WELCOME</div><h1>Every mystery starts<br>with a useful clue.</h1><p>Pick a case. Follow Remy. Show how you think.</p></section><div class="cases">${cases.map(c=>`<article class="case"><div class="art"><img src="assets/case${c.id}.png" alt="Illustration from ${esc(c.title)}"></div><div class="case-body"><div class="eyebrow">CASE 0${c.id} · FIVE THINKING MISSIONS</div><h2>${c.title}</h2><p>${c.description}</p><div class="actions">${c.interactive?'<a class="button" href="#case2">Open interactive case</a>':''}<a class="button secondary" href="assets/${c.pdf}" target="_blank" rel="noopener">Read / print PDF</a></div><p class="status">${c.interactive?'All five interactive missions are ready.':'PDF edition · interactive version deferred.'}</p></div></article>`).join('')}</div><p class="review">Read either case as a PDF, or join all five interactive missions in Case 2. Your progress stays in this browser.</p>`;}
function opening(){app.innerHTML=`<article class="story"><a class="back" href="#library">← Case library</a><div class="eyebrow">CASE 02 · YOUR CASE FILE</div><h1>The Case of the Runaway Robot</h1><img src="assets/case2.png" alt="Remy and the team with DASH-3 at the invention expo"><p>At the OddSpark Invention Expo, strange ideas are normal. A delivery robot racing away with the most important trophy at the fair? That is a case.</p><div class="check"><strong>You do not need to know the perfect path before you begin.</strong><p>Look for a fact or clue you can start with.<br>Use it to try a path.<br>Check your path.<br>Revise if you need to.</p></div>${caseProgress()}<h2>Welcome to OddSpark</h2><img class="story-art" src="assets/case2-page3.png" alt="Calamari presents DASH-3 beside the parcel and trophy, with Remy and Cammy watching."><p>At 2:25, the expo buzzed, clanked, flashed, and—near Booth 12—made a noise like a duck sneezing into a trumpet.</p><p>Remy adjusted his detective cap. “Excellent. Everything here looks suspicious.” Above the stage: GOLDEN QUESTION MARK PRESENTATION — 3:00.</p><p>Sunburned Calamari introduced DASH-3. “He can scan a label, find the matching destination, and deliver almost anything.” Beside the robot sat a silver parcel labeled FINAL PRIZE. Gleaming next to the silver parcel was the Golden Question Mark trophy.</p><p>Cammy began, “Let me overthink this. Did you check what happens when two objects have the same—” Calamari grinned. “What could go wrong?”</p><h2>BEEP. SCAN. GONE.</h2><img class="story-art" src="assets/case2-page4.png" alt="DASH-3 races away with the Golden Question Mark trophy as the startled detectives follow."><p>DASH-3’s scanner flashed. BEEP. Two robot arms lifted the Golden Question Mark trophy. WHIRRRR. The robot rolled offstage and vanished.</p><p>“A runaway robot. A missing trophy,” said Remy. “This has all the signs of an International Robot Trophy Syndicate.” Cammy asked, “Is that real?” “It has an official name,” said Remy. “That is usually a strong start.”</p><p>Behind the curtain, several observations waited—but not all would help. The clock read 2:27. The detectives had until 3:00. Their clock was running. Yours is not.</p><a class="button" href="#mission1">${s.path||s.chosen.length?'Resume':'Begin'} Mission 1</a></article>`;}
function mission(){app.innerHTML=`<article class="mission"><a class="back" href="#case2">← Back to the story</a><div class="eyebrow">CASE 02 · MISSION 1 OF 5</div><h1>The First Useful Trail</h1><div class="goal"><strong>YOUR GOAL</strong><p>Figure out where DASH-3 went.</p><span>Use the six facts to decide where the team should investigate first.</span></div><h2>Choose your useful facts</h2><p>Select the facts you would use. You can change your choices as you think.</p><div class="clues">${facts.map((f,i)=>`<label class="clue"><input type="checkbox" data-fact="${i}" ${s.chosen.includes(i)?'checked':''}><span><b>FACT ${String.fromCharCode(65+i)}</b>${f}</span></label>`).join('')}</div><section class="notebook"><h2>Show Your Path</h2><label class="field" for="path">How do your chosen facts connect?</label><textarea id="path" placeholder="I started with… Then I noticed…">${esc(s.path)}</textarea><div class="check"><label><input id="spoken" type="checkbox" ${s.spoken?'checked':''}><span>I explained or drew my path with a grown-up instead.</span></label></div><div class="check"><strong>Check your path</strong><p>Could you still choose where to investigate using only the facts you selected?</p><label><input id="checked" type="checkbox" ${s.checked?'checked':''}><span>I checked my path. I can revise it if I need to.</span></label></div><label class="field" for="answer">Your Answer: where should Remy investigate?</label><input type="text" id="answer" value="${esc(s.answer)}" placeholder="My next place to investigate is…"><div class="actions"><button id="check-answer">Check My Answer</button><button id="continue" class="secondary" ${s.verified?'':'disabled'}>Continue the Story</button></div><p id="message" role="status" aria-live="polite">${feedback?esc(feedback.text):'Check your answer to unlock the next part of the story.'}</p><div id="retry-actions" class="actions" ${feedback?.kind==='retry'?'':'hidden'}><button id="retry" class="secondary">Try Again</button><button id="retry-hint" class="secondary">Go to optional hints</button></div><p class="status">Your explanation stays in your thinking record. It is not automatically graded.</p><p class="status" id="saved"></p></section><section id="hint-section" tabindex="-1"><h3>Need a foothold?</h3><p>Reveal one hint at a time. Stop when your thinking starts moving again.</p><div id="hints">${hints.slice(0,s.hints).map((h,i)=>`<p class="hint"><strong>${i===3?'Strong hint':'Hint '+(i+1)}</strong><br>${h}</p>`).join('')}</div><button id="hint" class="secondary" ${s.hints===4?'disabled':''}>${s.hints===4?'All hints revealed':s.hints===3?'Reveal the strong hint':'Show the next hint'}</button></section></article>`;
function invalidate(){s.verified=false;s.complete=false;feedback=null;document.getElementById('continue').disabled=true;document.getElementById('message').textContent='You changed your path. Check your answer again.';document.getElementById('retry-actions').hidden=true;save();}
app.querySelectorAll('[data-fact]').forEach(e=>e.onchange=()=>{const i=Number(e.dataset.fact);s.chosen=e.checked?[...s.chosen,i]:s.chosen.filter(x=>x!==i);invalidate();});
for(const id of ['path','answer'])document.getElementById(id).oninput=e=>{s[id]=e.target.value;invalidate();};
for(const id of ['checked','spoken'])document.getElementById(id).onchange=e=>{s[id]=e.target.checked;invalidate();};
function nextHint(){s.hints=Math.min(4,s.hints+1);save();const y=scrollY;mission();scrollTo(0,y);document.getElementById('hints').scrollIntoView({block:'nearest'});}
document.getElementById('hint').onclick=nextHint;
document.getElementById('retry-hint').onclick=()=>{const section=document.getElementById('hint-section');section.scrollIntoView({block:'start'});section.focus({preventScroll:true});};
document.getElementById('retry').onclick=()=>{document.getElementById('answer').focus();};
document.getElementById('check-answer').onclick=()=>{feedback=evaluateAnswer(s);s.verified=feedback.kind==='success';s.complete=false;if(s.verified)awardMission(1);save();document.getElementById('message').textContent=feedback.text;document.getElementById('continue').disabled=!s.verified;document.getElementById('retry-actions').hidden=feedback.kind!=='retry';};
document.getElementById('continue').onclick=()=>{if(!s.verified||evaluateAnswer(s).kind!=='success')return;s.complete=true;save();location.hash='trail';};save();mountNavigation();}

function trail(){if(!missionSolved(1)){location.hash='mission1';return;}app.innerHTML=`<article class="story"><div class="eyebrow">MISSION 1 · THE STORY CONTINUES</div><h1>A Trail with Two Points</h1><p>“These tracks match DASH-3’s wheels,” said Cammy. “And they lead toward North Concourse,” said Calamari.</p><p>Remy circled those facts. “The locked passage helps too. The balloon and ribbon are dismissed.” A balloon popped. “Temporarily dismissed.”</p><div class="check"><h2>Compare paths</h2><p>The wheel tread and matching tracks point toward North Concourse. The sealed passage provides another check. How does that compare with your path?</p><p>A strong thinker does not always know the answer first. A strong thinker knows how to keep moving.</p></div><p>The tracks vanished where a floor-cleaning machine had polished the tiles. A tracking screen still showed DASH-3’s last signal, but most numbers were missing.</p><p>“A half-labeled tracker,” Remy whispered. “Very clue-ish.” The clock read 2:32.</p><div class="actions"><a class="button" href="#mission2">Begin Mission 2</a><a class="button secondary" href="#mission1">Revisit my path</a><a href="#library">Case library</a></div></article>`;}
function render(){const route=location.hash.slice(1);if(!routeAllowed(route)){location.hash=lastUnlockedRoute();return;}if(route==='case2')opening();else if(route==='mission1')mission();else if(route==='trail')trail();else if(/^mission[2-5]$/.test(route))extraMission(Number(route.at(-1)));else if(/^after[2-5]$/.test(route))extraStory(Number(route.at(-1)));else if(route==='reflection')reflection();else library();mountNavigation();scrollTo(0,0);}window.addEventListener('hashchange',render);
if(document.modelContext?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'read_case_progress',description:'Read the learner’s saved Mission 1 progress without revealing hints or story answers.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return {case:2,mission:1,selectedFacts:s.chosen.map(i=>String.fromCharCode(65+i)),path:s.path,answer:s.answer,checked:s.checked,complete:s.complete};}},{signal:life.signal})).catch(()=>{});}catch{}}
